save(264,dict(paragraphs=["Geethanjali Dilip is a poet and French educator associated with Zone Francofone in Salem, Tamil Nadu. Her literary work includes collaborative anthologies and the curation of the Yercaud Poetry Festival. Her collections include Geethatmaa: Song of the Soul and Rosée: The Dewdrop.","The poems gathered here move between intimate connection and public grief. ‘Lines’ follows a relationship beyond telephone wires into the quiet language of touch. ‘When it all reflects’ brings together images of womanhood and the earth’s abundance, while ‘Wasted Penance’ questions the human cost hidden beneath war songs, medals and patriotic ceremony."],sources=[source('Setu — Geethanjali Dilip, March 2019','https://www.setumag.com/2019/03/geethanjali-dilip-india.html',['Zone Francofone in Salem, teaching French; collaborative poetry and festival curation.']),source('Setu — The Mahatma, October 2023','https://www.setumag.com/2023/10/the-mahatma-gandhian-philosophy.html',['Contributor biography names Geethatmaa and Rosée; Yercaud festival curation.'],'search_index'),source('Sujatha Warrier — Book launch at Mysuru','https://www.sujathawarrier.com/2024/01/book-launch-pranayam-limited-version.html',['Participant account of Geethanjali launching a book as festival curator in January2024.'],'search_index')],identity_match='Captured French teaching centre, festival role and distinctive collection titles match literary journal biographies and participant launch account.',poems_read=[dict(id=252,title='When it all reflects',basis='Full original read: feminine earth imagery, nourishment, natural forces and duality.'),dict(id=435,title='Lines',basis='Full original read: telephone infrastructure, birds, accumulated conversation and silent touch.'),dict(id=728,title='WASTED PENANCE',basis='Full original read: war announcements, grieving families, medals, patriotic songs, burial and frustrated peace.')],limitations=['Dated sources give differing collection totals and festival naming; no current total or exclusive current appointment claimed.','Awards omitted without awarding-body verification.','No verified direct book product page found; no purchase link added.'],next_action='Independent author/editor review; verify preferred book links.'))
